      if (wide) V.text(g, mLbl, Pg[0] + 12, Pg[1] + 38, { size: 11, color: S8.ctx === 'none' ? C.muted : C.a, maxW: Pg[2] - 24 });
      else V.text(g, mLbl, Pg[0] + Pg[2] - 12, Pg[1] + 20, { size: 11, align: 'right', color: S8.ctx === 'none' ? C.muted : C.a });
