    const measure = (g, s, sz, f = 'sans', wt = 400) => { setFont(g, sz, f, wt); return g.measureText(String(s)).width; };
    const num = (v, d = 2) => (+v).toFixed(d).replace('.', ',');
    const fmtInt = (n) => Math.round(n).toLocaleString('pt-BR');
