      const w = Math.max(o.minW || 0, measure(g, s, sz, f, wt) + px * 2);
      if (o.dry) return w;
      if (o.glow) V.glow(g, x + w / 2, y + hh / 2, Math.max(w, hh) * 0.75, o.glow, 0.45);
