            V.text(g, SUP[r].x, 22, y + (rh - 7) / 2 + 4, { size: szs, font: 'mono', color: C.ink, maxW: ww - 16 });
            V.text(g, '→', 14 + ww + 10, y + (rh - 7) / 2 + 5, { size: 13, color: C.muted });
