      UI.seg(c8, { label: 'Pontos de treino', options: [10, 30, 100], value: 10, onChange: (v) => { S.N = v; compute(); } });
      UI.toggle(c8, { label: 'regularização (weight decay)', value: false, onChange: (v) => { S.reg = v; compute(); } });
