        const B = wide ? { x: w * 0.62 + 20, y: 30, w: w * 0.38 - 40, h: h - 76 } : { x: 50, y: h * 0.56 + 18, w: w - 70, h: h * 0.44 - 70 };
        const Y0 = -1.7, Y1 = 1.7;
