        { const ly = A.y + A.h + 18; let x = A.x; V.dot(g, x + 5, ly - 4, 4, C.a); V.text(g, 'treino', x + 13, ly, { size: 11, color: C.muted }); x += 13 + measure(g, 'treino', 11) + 14;
          g.strokeStyle = C.b; g.lineWidth = 1.3; g.beginPath(); g.arc(x + 5, ly - 4, 3.5, 0, Math.PI * 2); g.stroke(); V.text(g, 'validação', x + 13, ly, { size: 11, color: C.muted }); x += 13 + measure(g, 'validação', 11) + 14;
          V.line(g, x, ly - 4, x + 16, ly - 4, { color: V.alpha(C.ink, 0.5), dash: [4, 3] }); V.text(g, 'verdadeira', x + 21, ly, { size: 11, color: C.muted }); x += 21 + measure(g, 'verdadeira', 11) + 14;
          if (x + 90 < A.x + A.w) { V.line(g, x, ly - 4, x + 16, ly - 4, { color: C.c, lw: 3 }); V.text(g, 'modelo', x + 21, ly, { size: 11, color: C.muted }); } }
        // curvas de erro
