        V.text(g, 'grau →', B.x + B.w, B.y + B.h + 30, { size: 11, color: C.muted, align: 'right' });
        V.text(g, 'ERRO (MSE, escala log)', B.x, B.y - 12, { size: 10.5, font: 'mono', color: C.muted });
