        err: { lab: 'gate por cabeça: [T, 64, 128] ⊙ [64]', A: ['T', 64, 128], B: [64], op: '⊙', note: 'Alinhando pela direita, 64 encontra 128: erro. (Ilustrativo, inspirado no gate por cabeça do KDA.)', recipe: 'ilustrativo' },
