        let d = fr * tot;
        for (let q = 0; q < L.length; q++) { if (d <= L[q] || q === L.length - 1) { const u = L[q] ? Math.min(1, d / L[q]) : 0; return [V.lerp(pts[q][0], pts[q + 1][0], u), V.lerp(pts[q][1], pts[q + 1][1], u)]; } d -= L[q]; }
