        for (let i = 0; i < n - 1; i++) for (const a of subs(i)) for (const b of subs(i + 1)) { g.strokeStyle = V.alpha(C[FAM[st(i, a).tok][0]], 0.55); g.lineWidth = 5; path(g, seg(i, a, b)); g.stroke(); }
