        const PER = 5.5, cyc = Math.floor(t / PER), f = (t % PER) / PER;
        if (atom() && cyc !== S.lastCyc) { if (S.lastCyc >= 0) { S.run++; compute(); } S.lastCyc = cyc; }
        else if (!atom()) S.lastCyc = cyc;
