        const bw = Math.min(150, w * 0.2), by = 40;
        const mx0 = narrow ? pad : pad + bw + 34, ky = narrow ? 34 + sqN + 46 : 48;
        const nPR = narrow && ns > 4 ? 4 : ns, pRowsN = Math.ceil(ns / nPR);
