        const per = 1.1, hold = 1.8;
        const el = (t - S.t0) % (T * per + hold);
        const cur = Math.min(T - 1, Math.floor(el / per));
        const u = el >= T * per ? 1 : (el - cur * per) / per;
        const done = el >= T * per ? T : cur;
