        g.strokeStyle = C.grid; g.lineWidth = 1;
        g.beginPath(); g.moveTo(ox - sc * 1.1, oy); g.lineTo(ox + sc * 1.1, oy); g.moveTo(ox, oy - sc * 1.1); g.lineTo(ox, oy + sc * 1.1); g.stroke();
        V.dot(g, ox, oy, 3, C.muted);
