      let r = V.clamp(u, 0, 1) * L;
      for (let i = 0; i < seg.length; i++) { if (r <= seg[i] || i === seg.length - 1) { const f = seg[i] ? r / seg[i] : 0; return V.along(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1], Math.min(1, f)); } r -= seg[i]; }
