        T(g, 'Norm', norm.x + norm.w / 2, norm.y + norm.h / 2 + 4, { size: 11.5, align: 'center', weight: 600, color: C.ink });
        if (wide) T(g, 'final', norm.x + norm.w / 2, norm.y + norm.h + 14, { size: 11, align: 'center', color: C.muted });
        // chip do token
