        const chipAlpha = f < 0.12 ? 1 : 0.35;
        V.box(g, chip.x, chip.y, chip.w, chip.h, { r: 10, fill: V.alpha(C.d, 0.18 * chipAlpha + 0.05), stroke: V.alpha(C.d, chipAlpha), lw: 1.5 });
