          if (S.wrong) V.text(g, narrow ? 'rosa (embaixo): os pares que o kernel juntaria' : 'arcos rosa embaixo: os pares que o kernel juntaria com a convenção errada (sem erro nenhum)', w / 2, zy + zh + below + 32, { size: 11.5, align: 'center', color: C.c, weight: 600, maxW: w - 20 });
