          V.text(g, ttl, w / 2, by0 + 10, { size: 11.5, align: 'center', color: C.ink, weight: 600, maxW: w - 20 });
          const px0 = 40, px1 = w - 18, py0 = by0 + 22, py1 = by0 + blockH - (cv && S.wrong ? 32 : 16);
