          V.text(g, '24 tokens atrás', px1, py1 + 13, { size: 11, font: 'mono', align: 'right', color: C.muted });
          if (cv) V.line(g, X(LOOK), py0, X(LOOK), py1, { color: V.alpha(C.a, 0.4), lw: 1, dash: [3, 4] });
          const sd = (t * 5) % (DMAX + 1);
