          const grid = (bx, by, st2, cs2) => { for (let q = 0; q < 16; q++) { g.fillStyle = V.cmap(st2[q] / smax, 'div'); V.rr(g, bx + (q % 4) * cs2, by + Math.floor(q / 4) * cs2, cs2 - 2, cs2 - 2, 2); g.fill(); } };
          const bx = V.clamp(sx - gw / 2, 8, w - gw - 8), byy = beltY + 10;
          grid(bx, byy, st0, gs);
