          V.text(g, 'ordem real', cxA + cg / 2, cy2 - 8, { size: 11.5, align: 'center', color: C.ink, weight: 600 });
          V.text(g, '“chave” ↔ “vaso”', cxB + cg / 2, cy2 - 8, { size: 11.5, align: 'center', color: C.ink, weight: 600 });
          const diff = Math.sqrt(st0.reduce((sm, v, q) => sm + (v - stS[q]) * (v - stS[q]), 0));
          V.text(g, cur < 1 ? 'antes de “chave”: estados iguais' : 'estados diferentes (‖ΔS‖ = ' + sf(diff, 2) + '): a ordem ficou gravada', w / 2, cy2 + cg + 20, { size: 12, align: 'center', color: cur < 1 ? C.muted : C.d, weight: 600, maxW: w - 20 });
          V.text(g, 'Sₜ = α·Sₜ₋₁ + (escrita do token t)   [esquemático]', w / 2, h - 12, { size: 12, font: 'mono', align: 'center', color: C.ink, maxW: w - 20 });
