          const rq = V.rng(7), qv = Array.from({ length: n }, () => rq.normal() * 0.7), kvv = Array.from({ length: n }, () => rq.normal() * 0.7);
          const rowsY = [52, 52 + cs + 26, 52 + 2 * (cs + 26)];
