      const S = { p: 'qwen', meth: 'yarn', s: 4, from: null, t0: -10, cur: null, ms: true, fcur: 1 };
      const LG = [2.2, 1.6, 1.3, 1.0, 0.8, 0.5, 0.3, 0.0]; // logits ilustrativos para o painel da temperatura
      const d = 64;
      function target() {
        const P = PRE[S.p], o = ropeInv(P.base, d);
        if (S.meth === 'none') return o;
        if (S.meth === 'pi') return o.map((x) => x / S.s);
        if (S.meth === 'ntk') return ropeInv(P.base * Math.pow(S.s, d / (d - 2)), d);
        return yarnInv(P.base, d, P.L, S.s).inv;
      }
      let H = null;
      function change() { S.from = S.cur ? S.cur.slice() : target(); S.t0 = H ? H.t : 0; upd(); }
      const ctl = UI.controls(fig);
      UI.seg(ctl, { label: 'cenário', options: [{ v: 'qwen', label: 'Qwen ×4' }, { v: 'ds', label: 'DeepSeek ×16' }], value: 'qwen', onChange: (v) => { S.p = v; sS.set(PRE[v].s); if (tgMs) tgMs.set(v === 'qwen'); change(); } });
      UI.seg(ctl, { label: 'método', options: [{ v: 'none', label: 'nenhum' }, { v: 'pi', label: 'PI' }, { v: 'ntk', label: 'NTK' }, { v: 'yarn', label: 'YaRN' }], value: 'yarn', onChange: (v) => { S.meth = v; change(); } });
      const sS = UI.slider(ctl, { label: 'fator s', min: 1, max: 32, step: 1, value: 4, fmt: (v) => '×' + v, onInput: (v) => { S.s = v; change(); } });
      /* mscale do YaRN: multiplica cos e sin, então os logits saem × mscale². Qwen usa (padrão do HF); o DS zera. */
      const tgMs = UI.toggle(ctl, { label: 'mscale (temperatura)', value: true, onChange: (v) => { S.ms = v; upd(); } });
      const rK = UI.readout(ctl, 'intactos · rampa · interpolados', '—'), rM = UI.readout(ctl, 'mscale', '—');
      function upd() {
        const P = PRE[S.p], y = yarnInv(P.base, d, P.L, 2);
        const c = { K: 0, R: 0, I: 0 }; y.kind.forEach((k) => { c[k]++; });
        rK.set(c.K + ' · ' + c.R + ' · ' + c.I);
        const ms = mscaleOf(S.s);
        rM.set(S.meth !== 'yarn' ? '—' : !S.ms ? (S.p === 'ds' ? '1 (mscale=0 no DS)' : '1 (desligado)') : sf(ms, 3) + ' · logits ×' + sf(ms * ms, 3) + (S.p === 'ds' ? ' (DS não usa)' : ''));
      }
