          V.text(g, sf(degc, 1) + '°/token (original ' + sf(deg0, 1) + '°)', bx0, yy + 32, { size: 12, font: 'mono', weight: 700, color: degc < deg0 - 0.01 ? C.c : C.a, maxW: bw2 });
