      const upd = () => { const m = model(S.B); rD.set(distinct(S.B) + ' de 512'); rA.set(nf(m.A, 0) + ' tok/s'); rS.set(nf(m.s, 1) + ' tok/s'); rQ.set(String(Math.max(0, S.B - SEQS))); };
