          rowLabels(P[0], T);
          tmat(g, P[1].x, P[1].y, D.Os, P[1].cs, { label: TX.osLab, max: 1.5, reveal: (a) => (a < sr ? 1 : 0.1), hiRow: sr <= T && el < T * per + 0.4 ? sr - 1 : null, hiColor: C.b });
          if (!narrow) tmat(g, P[2].x, P[2].y, D.Se, P[2].cs, { label: TX.seLab, labelColor: TFC, max: 1.5 });
