          ['H₀', 'H₁', 'H₂', 'H₃'].forEach((s2, i) => { const p = P(0, i); txt(g, s2, p[0] - 6, p[1] + 4, { size: 11, align: 'right', color: cols[i], font: 'mono' }); });
          const yb = P(1, 3)[1] + 52;
