          V.box(g, x + 1.5, axisY, cw - 3, 22, { r: 5, fill: cur ? V.alpha(C.c, 0.35) : isTap ? V.alpha(C.d, 0.3) : V.alpha(C.muted, 0.1), stroke: cur ? C.c : isTap ? C.d : V.alpha(C.muted, 0.3), lw: isTap || cur ? 1.5 : 1 });
          const lb = i === tIdx ? 't' : 't-' + (tIdx - i);
