        if (S.sc === 'spec') cur = N - 1; else if (S.sc === 'eos') cur = eosAt + [1, 2, 3, 1, 2, 3, -1][Math.floor(t * 0.8) % 7]; else cur = (Math.floor(t * 1.2) + S.C) % N;
