          nv: [c5, r[1]], fp8: [c5, r[2]], bfx: [c5, r[3]],
          skip: [cx(1), r[3]], f8c: [cx(2), r[3]], sw0: [cx(2), r[4]], bf: [c5, r[4]],
          v30: [cx(1), r[5]], nat: [cx(2), r[5]],
          ghost: [(cx(2) + cx(3)) / 2 + 20, 26], off: [c5 - 32, r[5] + 4], c5,
