        V.line(g, x - gw / 2 + 8, y, x + gw / 2 - 8, y, { color: V.alpha(RED(), 0.85), lw: 1.6 });
        V.text(g, 'só no README: nenhum arquivo lê', x, y + 28, { size: 11, align: 'center', color: C.muted });
