          const edgeOn = (a, b) => { const i = ck.path.indexOf(a); return i >= 0 && ck.path[i + 1] === b; };
          edges.forEach(([a, b]) => { const eo = edgeOn(a, b); drawEdge(g, P[a], P[b], eo ? C.c : V.alpha(C.muted, 0.28), eo ? 3 : 1.4, !eo); });
