      const sK = UI.slider(ctl, { label: 'k', min: 1, max: 9, step: 1, value: 3, onInput: (v) => { S.k = v; } });
      UI.toggle(ctl, { label: 'block-k (DSpark isento)', value: false, onChange: (v) => { S.blockK = v; } });
