        for (let i = 0; i < N; i++) {
          let mx = 1e-12; for (let j = 0; j < N; j++) mx = Math.max(mx, A[i * N + j]);
          for (let j = 0; j < N; j++) {
            const o = (i * N + j) * 4;
            const c = mode === 'causal' && j > i ? bgc : rgbOf(V.cmap(Math.sqrt(A[i * N + j] / mx), 'heat'));
            im.data[o] = c[0]; im.data[o + 1] = c[1]; im.data[o + 2] = c[2]; im.data[o + 3] = 255;
          }
        }
