        V.text(g, causal ? (q === 0 ? 'causal: o canto só enxerga a si mesmo' : `causal: vê só ${vis} patches (os anteriores)`) : 'bidirecional: vê os 64 patches', gx, gy + G + 20, { size: 12.5, font: 'mono', color: causal ? C.c : C.a, maxW: G + (mob ? 0 : 60) });
