            const x = gx + c * cs, y = gy + r * cs, m = 4, bw = (cs - 2 * m) * pop, bh = (cs - 2 * m) * pop, cx = x + cs / 2, cy = y + cs / 2;
            const gi = gOf(r, c), dim = selG >= 0 && gi !== selG;
