            const rr = V.rng(900 + gi), bh2 = (sz * 0.5) / 6;
            for (let s = 0; s < 6; s++) { g.fillStyle = V.alpha(colR, 0.25 + 0.6 * Math.abs(Math.sin(rr() * 6 + t * 0.8 + s))); g.fillRect(x + sz * 0.22, y + sz * 0.18 + s * bh2 * 1.15, sz * 0.56, bh2 * 0.8); }
