        panel.innerHTML = '';
        panel.appendChild(h('div', { class: 't18-req' },
          h('h5', null, ROWS[r].l, ' · ', NAME[m], h('span', { class: 'st', style: { background: V.alpha(colOf(C, cell[0]), 0.2), color: 'var(--text)', border: '1px solid ' + colOf(C, cell[0]) } }, stName[cell[0]])),
          h('div', { html: cell[1] })));
