          const blink = (Math.floor(t * 1.3 + i * 0.37) % 7) === 0 ? 0.6 : 2;
          V.box(g, fx - 5, fy - 3, 2.6, blink * 2, { r: 1, fill: C.ink }); V.box(g, fx + 2.6, fy - 3, 2.6, blink * 2, { r: 1, fill: C.ink });
