        const allRows = sideAsRow ? [{ l: 'estado', items: mp.side }].concat(rows) : rows;
        const towerW = sideAsRow ? w - 2 * pad : w * 0.7 - pad;
        const rowLab = narrow ? 0 : 74;
        const top = 12, bottom = h - infoH - 10;
        const rh = (bottom - top) / allRows.length;
