        V.glow(g, tx, ty, 14, C.d, 0.9); V.dot(g, tx, ty, 4, C.d);
        // caixa de explicação
        const iy = h - infoH - 2;
        V.box(g, pad, iy, w - 2 * pad, infoH - 4, { r: 10, fill: V.alpha(C.muted, 0.08), stroke: V.alpha(C.muted, 0.25), lw: 1 });
        const txt = active
