          T(g, clip(g, '(i, j) → byte 8+N+b+' + DTB[sel.dt] + '·(i·' + c0 + '+j)', dw - 24, 11, 'mono'), cx, gy + 22, { size: 11, font: 'mono', color: C.ink });
