        V.line(g, x0, yU, x1, yU, { color: V.alpha(dead ? C.muted : C.b, dead ? 0.25 : 0.6), lw: 3, dash: dead ? [4, 6] : null });
        const cx = (k) => x0 + 20 + k * Math.min(90, (x1 - x0 - 40) / 4.5);
        const commits = [{ l: '5ab363a8', real: true }];
