        // espelho
        V.line(g, x0, yM, x1, yM, { color: V.alpha(C.a, 0.6), lw: 3 });
        const mx = cx(0) + 40;
        V.dot(g, mx, yM, 8, C.a);
        T(g, '25a44fdb', mx, yM + 24, { size: 10, font: 'mono', align: 'center', color: C.ink });
        bezLine(g, cx(0), yU + 8, mx, yM - 8, { color: V.alpha(C.a, 0.6), lw: 1.4, dash: [4, 4], dashOffset: -t * 12 }, false);
