        const relD = prev ? V.lerp(prev.rel, res.rel, uG) : res.rel;
        const rowsD = prev ? res.rows.map((v, r) => V.lerp(prev.rows[r], v, V.ease.inOut(V.clamp((el - r * 0.008) / 0.5, 0, 1)))) : res.rows;
        // medidor
        const amax = 0.14;
        const X = (v) => gx0 + V.clamp(v / amax, 0, 1) * gW;
        const yb = gy0 + 36;
