        g.fillStyle = V.alpha(C.a, 0.15); g.fillRect(hx, 22, hsW * prog, 4);
        g.fillStyle = V.alpha(C.muted, 0.12); g.fillRect(hx + hsW * prog, 22, hsW * (1 - prog), 4);
        const Lay = layout(T, nb, canon);
