        core: { lab: 'núcleo', ab: 'núc.', idle: 2.0, site: 'o' },
        o: { lab: 'saída', ab: 'saí.', mib: 12 },
        ag1: { lab: 'AG + cola', ab: 'AG', idle: 2.4, site: 'a' },
        sh: { lab: 'comp.', ab: 'c.', mib: 12 },
