          chips(xs.map((x) => [`e^${f(x, 1)}`, f(Math.exp(x), 4), C.b]), py);
          chips(xs.map((x) => [`2^(${f(x, 1)}·1,4427)`, f(Math.pow(2, x * 1.4426950408889634), 4), C.a]), py + 46);
