      const sp = UI.seg(ctl, { label: 'Perfil', options: [{ v: 'stock', label: 'stock (GB300)' }, { v: 'gb10', label: 'gb10' }, { v: 'manual', label: 'manual' }], value: 'stock', onChange: (v) => { S.prof = v; upd(); } });
