      const K = 4096, N = 12576, BW = 230e9, M0 = 7168, P = 4;
      const meas = { marlin: 27.21, w8a8: 12.57, bf16: 7.36 };
      const bytes = { marlin: (M) => K * N + 2 * M * K + 2 * M * N, w8a8: (M) => K * N + 3 * M * K + 2 * M * N, bf16: (M) => 2 * K * N + 2 * M * K + 2 * M * N };
