          if (S.st === 'legacy') { q.fat.slice(0, 9).forEach((c) => boxes.push({ l: 'recon+GEMM', s: `${c} linhas`, c: C.c, sync: true })); if (q.fat.length > 9) boxes.push({ l: `+${q.fat.length - 9}`, s: 'fat', c: C.c }); }
