          V.text(g, 'forma fixa [E+1], fica na GPU ✓', tx, ty + 20, { size: 11.5, color: C.a, weight: 700, maxW: tW });
          V.text(g, 'searchsorted → segmentos de linhas', tx, ty + 38, { size: 11, color: C.muted, maxW: tW });
