        pool: 'rank 0 · pool de linhas por token (1 casa = 2.048 tokens)',
        queue: 'fila (prompt em casas)', empty: '— vazia',
        msgs: 'mensagens do rank 0 (uma por iteração)', r1: 'rank 1 · aplica as mesmas operações',
