        if (S.sc === 'edit') { const cur = cont.map((o, i) => (i === S.edit ? { x: '✎' + o.x, c: 'edit' } : o)); return { prev: base, cur, sp: '', sc: '' }; }
        if (S.sc === 'salt') return { prev: base, cur: cont, sp: '', sc: 'cliente-B' };
