        return { prev: [...cat(BOS, 'bos'), ...cat(SYS, 'sys'), ...cat(TOOLS, 'tool'), ...cat(DH, 'dir'), ...cat(Q1, 'user')], cur: [...cat(BOS, 'bos'), ...cat(SYS, 'sys'), ...cat(TOOLS, 'tool'), ...cat(DM, 'dir'), ...cat(Q1, 'user')], sp: '', sc: '' };
