      const per = () => {
        const Sg = Math.floor(S.L / 3584); const R = S.glob;
        const mla = Sg;
        const mamba = R === 'd' ? 4 * Sg : R === 0 ? 4 : 4 * Math.floor(S.L / R) + 4;
        const draft = S.swa === '0' ? 33 : R === 'd' ? 33 * Sg : R === 0 ? 33 : 33 * Math.floor(S.L / R) + 33;
        return { Sg, mla, mamba, draft, tot: mla + mamba + draft };
      };
