        const bl = wrap(g, `histórico de ${K}K editado em ${sf(S.edit, S.edit % 1 ? 1 : 0)}% (LCP ${nf(e)}): volta ao último checkpoint de estado que sobreviveu antes da edição`, gx, by, gw, { size: 11.5, color: C.muted });
