      UI.slider(ctl, { label: L.size, min: 8, max: 128, step: 8, value: S.k, fmt: (v) => v + 'k', onInput: (v) => { S.k = v; upd(); } });
      UI.toggle(ctl, { label: L.grid, value: true, onChange: (v) => { S.grid = v; upd(); } });
