      g.setLineDash([]);
      V.text(g, s, x + w / 2, y + hh / 2 + 0.5, { size: sz, font: f, weight: wt, color: o.color || C.ink, align: 'center', base: 'middle', alpha: o.alpha });
      if (o.strike) V.line(g, x + 4, y + hh / 2, x + w - 4, y + hh / 2, { color: o.strike, lw: 1.4 });
