      const lines = [];
      let cur = '';
      words.forEach((wd) => { const tst = cur ? cur + ' ' + wd : wd; if (cur && measure(g, tst, sz, f, wt) > maxW) { lines.push(cur); cur = wd; } else cur = tst; });
      if (cur) lines.push(cur);
