      qwen: [['Vou', 'txt', 0], [' consultar.', 'txt', 0], ['<tool_call>', 'syn', 1], ['<function=', 'syn', 1], ['get_weather', 'name', 2], ['>', 'syn', 2], ['<parameter=', 'syn', 3], ['city', 'key', 3], ['>', 'syn', 3], ['Paris', 'val', 3], ['</parameter>', 'syn', 3], ['</function>', 'syn', 4], ['</tool_call>', 'syn', 4]],
      ds: [['Vou', 'txt', 0], [' consultar.', 'txt', 0], ['<｜DSML｜tool_calls>', 'syn', 1], ['<｜DSML｜invoke name="', 'syn', 1], ['get_weather', 'name', 2], ['">', 'syn', 2], ['<｜DSML｜parameter name="', 'syn', 3], ['city', 'key', 3], ['" string="true">', 'syn', 3], ['Paris', 'val', 3], ['</｜DSML｜parameter>', 'syn', 3], ['</｜DSML｜invoke>', 'syn', 4], ['</｜DSML｜tool_calls>', 'syn', 4]],
      dsx: [['Vou', 'txt', 0], [' consultar.', 'txt', 0], ['<｜DSML｜invoke name="', 'syn', 5], ['get_weather', 'name', 5], ['">', 'syn', 5], ['<｜DSML｜parameter name="', 'syn', 5], ['city', 'key', 5], ['" string="true">', 'syn', 5], ['Paris', 'val', 5], ['</｜DSML｜parameter>', 'syn', 5], ['</｜DSML｜invoke>', 'syn', 4]],
