        const lx = cx - Lb * Math.cos(a), ly = cy - Lb * Math.sin(a), rx = cx + Lb * Math.cos(a), ry = cy + Lb * Math.sin(a);
        V.line(g, lx, ly, rx, ry, { color: C.ink, lw: 3 });
        V.dot(g, cx, cy, 4, C.ink);
