          PROMPT.forEach((tk, i) => { const [x, yy] = slot(i, y0); chip(g, x, yy, sw, ch, WORDS[tk], { size, fill: V.alpha(C.muted, 0.08), stroke: V.alpha(C.muted, 0.3), color: C.muted }); });
