        let lx = 16; Mo.legend.forEach(([l, c]) => { V.rr(g, lx, 30, 10, 10, 2); g.fillStyle = V.alpha(C[c], 0.8); g.fill(); V.text(g, l, lx + 14, 39, { size: 11, color: C.muted }); lx += tw(g, l, 11) + 30; });
