          const mx0 = w * 0.36;
          for (let k = 0; k < nt; k++) { const yc = nt === 1 ? h * 0.3 : top + 20 + ((nt - 1 - k) + 0.5) * ((bot - top - 30) / nt); slabPos.push({ x: mx0, y: yc - slabH / 2, cs: cs2, w: slabW, h: slabH }); }
