          const nl = contract ? (S.mode === 'ds' ? 'cada escuta: 4 fluxos → média → 4096' : 'cada escuta: 4 fluxos × 4096 → hc_contract') : 'cada escuta entrega [t, 4, 4096]';
          const nlw = Math.min(w - 24, tw(g, nl, 11, 'mono'));
