          const w1 = tw(g, l1, 11.5, 'sans', 700), w2 = tw(g, l2, 11, 'mono', 400), lx = sx(mid) - (w1 + w2) / 2;
          V.text(g, l1, lx, aTop - 10, { size: 11.5, weight: 700, color: col });
