        { const [ax, ay] = pos(7), [bx, by] = pos(0); if (cur === 0) { V.line(g, ax + 6, ay + 10, bx + 6, by + nh - 10, { color: V.alpha(C.d, 0.6), lw: 1.4, dash: [4, 5], dashOffset: -t * 20 }); } }
