          if (tiny) { const parts = N.s.split(' '); const half = Math.ceil(parts.length / 2); [parts.slice(0, half).join(' '), parts.slice(half).join(' ')].forEach((ln, li) => V.text(g, ln, x + 6, y + nh - 22 + li * 12, { size: 9.5, font: 'mono', color: C.muted, maxW: nw - 10 })); }
