          V.line(g, xKV - 6, yb, xEnd, yb, { color: V.alpha(C.c, 0.7), lw: 1.4, dash: [5, 4], dashOffset: -t * 20 });
          const crossing = toks[0].row === 2 && toks[0].f < 0.08;
