          const r2 = [{ op: '=' }, { M: D.Y, col: nN, label: 'Y', sub: '[2×4]' }];
          const r3 = [{ op: 'f(', opW: 1.1, font: 'mono' }, { M: D.Y, col: nN, label: 'Y' }, { op: ')', opW: 0.5, font: 'mono' }, { op: '·' }, { M: D.W2, col: nN, label: 'W₂', sub: '[4×4]' }];
