      UI.seg(ctl, { label: 'Nó', options: [{ v: 'head', label: 'head' }, { v: 'worker', label: 'worker' }], value: S.node, onChange: (v) => { S.node = v; render(); } });
      UI.select(ctl, { label: 'Finalidade', options: CATS, value: S.cat, onChange: (v) => { S.cat = v; render(); } });
