        const W = Math.min(W0, c.np);
        const ws = c.np - W;
        const u = W / 16 <= 48 ? 16 : W / 32 <= 48 ? 32 : 64;
        const ncell = Math.ceil(W / u);
        const srcX0 = bx + (bwid * ws) / c.np, srcX1 = bx + bwid;
        const ly = by + bh + 66, lh = 46;
        const breathe = 0.5 + 0.5 * Math.sin(t * 2);
