        const narrow = w < 560;
        // faixa do checkpoint
        const cs = narrow ? 7 : 9, colW = cs * 1.7, sx0 = 16, sy0 = 34;
        V.text(g, 'checkpoint: 8 grupos × 8 cabeças', sx0, 20, { size: 11.5, color: C.muted });
