            if (hangs && r === 2 && S.x[r] < xStar1 && x >= xStar0 + (xStar1 - xStar0) * 0.55) { x = xStar0 + (xStar1 - xStar0) * 0.55; S.phase = 'hang'; S.timer = 0; }
            S.x[r] = x;
