          const [a, b] = key.split('>').map(Number);
          const s2 = shift(edge(a, PT[b][0], PT[b][1]), edge(b, PT[a][0], PT[a][1]), 15);
          chip(g, '×' + n, (s2[0][0] + s2[1][0]) / 2, (s2[0][1] + s2[1][1]) / 2, C.d, { size: 11 });
