          V.text(g, R.name, pad, y - 13, { size: 11, font: 'mono', weight: 700, color: col, alpha: on ? 1 : 0.5 });
          V.line(g, x0, y, x1, y, { color: V.alpha(col, on ? 1 : 0.28), lw: on ? 5 : 3 });
