          for (let q = 0; q <= 4; q++) V.line(g, x - 9, V.lerp(yB, yT, q / 4), x - 5, V.lerp(yB, yT, q / 4), { color: V.alpha(C.muted, 0.5), lw: 1 });
          const ky = V.lerp(yB, yT, u), col = C.series[i % 6], kw = narrow ? 24 : 30;
