      const counts = (e) => { let s = 0, m = 0, x = 0; ROWS.forEach((R) => R.st.forEach((S) => { if (S.hw) s++; else if ((e === 'v' ? S.v : S.f)[3] === 'x') x++; else m++; })); return [s, m, x]; };
