          if (T[3]) { v = 'fp8'; put(v, true, 'OVERRIDE_KV_CACHE_DTYPE=fp8'); } else if (T[2]) { v = 'auto'; put(v, true, 'start-v030.sh: OVERRIDE_KV_CACHE_DTYPE=${…:-auto}'); } else put(v, false, 'sem wrapper');
          put(v, false, 'sem guarda para esta chave');
          const lane030 = T[2];
