            if (u >= 1) { const mx = (a[0] + b[0]) / 2 + (narrow ? 26 : 0), my = (a[1] + b[1]) / 2; V.box(g, mx - 13, my - 12, 26, 24, { r: 12, fill: V.alpha(col, 0.3), stroke: col, label: i === 3 ? '✓' : '✕', size: 13, weight: 700 }); }
