              V.text(g, fitText(g, lab, pw - 12, { size: 11, font: 'mono' }), x + pw / 2, py + 4, { size: 11, font: 'mono', align: 'center', color: C.ink });
              if (k < 3) V.arrow(g, x + pw + 3, py, x + pw + 19, py, { color: V.alpha(C.muted, 0.8), lw: 1.5, head: 6 });
