          if (mx) { const nN = Math.floor(n / T), stepN = Math.max(1, Math.ceil(nN / 90)); for (let q = stepN; q <= nN; q += stepN) { const y = by + q * T * syN; if (y < by + bh - 0.5) { g.moveTo(bx, y); g.lineTo(bx + bw, y); } } }
