        gear(mx - 14, beltY + 2, narrow ? 10 : 13, t * 1.6, C.b); gear(mx + 14, beltY + 2, narrow ? 7 : 9, -t * 2.3, C.a);
        // saída: uma string que se divide nos dois ranks
