        if (S.Smax < 16) { const qx = XC(S.Smax + 0.5); g.fillStyle = V.alpha(C.d, 0.08); g.fillRect(qx, gy, gx + gw - qx, gh); V.text(g, 'fila (C > ' + S.Smax + ')', qx + 6, gy + 14, { size: 11, color: C.d }); }
