    const BITS = { bf16: 16, fp8: 8 + 32 / 16384, nvfp4: 4.5, mxfp4: 4.25 };
    const EXL3_OVH = 0.0117;           // suh/svh FP16: 0,457 GB / 311,65 B params (cálculo nosso)
