            const c2 = [colX(p1x, 1) + colW(1) / 2, rowY(p1y, i) + rowH / 2], d = [colX(p0x, 1) + colW(1) / 2, rowY(p0y, i) + rowH / 2];
            const mid1 = narrow ? [w / 2 - 30, (a[1] + b[1]) / 2] : [(a[0] + b[0]) / 2, midY - 10];
            const mid2 = narrow ? [w / 2 + 30, (c2[1] + d[1]) / 2] : [(a[0] + b[0]) / 2, midY + 10];
