      const pT = [0.90, 0.95, 0.90, 0.90, 0.60, 0.90, 0.70, 0.95, 0.05, 0.90];
      const opd = pT.map((x, i) => Math.log(x / pS[i]));
      // PPO: GAE (γ = 1, λ = 0,95) sobre um crítico ilustrativo, resposta errada (recompensa 0)
