      nocase(UI.slider(ctl, { label: 'N por modelo (bilhões)', min: 0.5, max: 14, step: 0.5, value: 7, fmt: (v) => nf(v, 1) + ' B', onInput: (v) => { S.N = v; upd(); } }));
