      const S = { arr: 'col', sig: 0.6, mis: false };
      const ctl = UI.controls(fig);
      wrapCtl(UI.seg(ctl, { label: 'Arranjo', options: [{ v: 'col', label: 'colocado' }, { v: 'des', label: 'desagregado' }, { v: 'asy', label: 'assíncrono' }], value: 'col', onChange: (v) => { S.arr = v; upd(); } }));
