      const rU = UI.readout(ctl, 'utilização da geração', '—'), rT = UI.readout(ctl, '3 iterações (u.a.)', '—');
      const lens = () => { const L = Z.map((z) => Math.exp(S.sig * z)); const m = L.reduce((a, b) => a + b, 0) / L.length; return L.map((x) => x / m); };
