        const lanes = [];
        if (S.arr === 'col') { const a = []; let x = 0; for (let i = 0; i < 3; i++) { a.push(['g', x, gen]); x += gen; a.push(['s', x, sc]); x += sc; a.push(['t', x, tr]); x += tr; a.push(['y', x, sy]); x += sy; } lanes.push({ n: 'todas as GPUs', segs: a }); return { lanes, total: lanes[0].segs.reduce((m, s) => Math.max(m, s[1] + s[2]), 0), L, mx }; }
        if (S.arr === 'des') { const a = [], b = []; let x = 0; for (let i = 0; i < 3; i++) { a.push(['g', x, gen]); a.push(['i', x + gen, sc + tr + sy]); b.push(['i', x, gen]); b.push(['s', x + gen, sc]); b.push(['t', x + gen + sc, tr]); b.push(['y', x + gen + sc + tr, sy]); x += gen + sc + tr + sy; } lanes.push({ n: 'GPUs de rollout', segs: a }, { n: 'GPUs de treino', segs: b }); return { lanes, total: x, L, mx }; }
        const a = [], b = []; let x = 0, bt = 0;
        for (let i = 0; i < 3; i++) { a.push(['g', x, gen]); const st = Math.max(x + gen, bt); if (st > bt) b.push(['i', bt, st - bt]); b.push(['s', st, sc]); b.push(['t', st + sc, tr]); b.push(['y', st + sc + tr, sy]); bt = st + sc + tr + sy; x += gen + 0.15; }
        if (x < bt) a.push(['i', x, bt - x]);
