            V.line(g, bx + (Math.min(prog, mx) / mx) * bwid, uy, bx + (Math.min(prog, mx) / mx) * bwid, uy + uh, { color: V.alpha(C.ink, 0.5), lw: 1, dash: [3, 3] });
