          if (role === 'w') act = ph === 0 || (!inf && ph === 3 && !r.frozen);
          if (role === 'g') fill = inf ? 0 : ph === 0 ? 0 : ph === 1 ? pf : ph === 4 ? 1 - pf : 1;
          if (role === 'm' || role === 'v') act = ph === 2;
