        if (p.kind === 'wsd') { if (x < p.stable) return p.peak; const q = (x - p.stable) / (1 - p.stable); return p.end + (p.peak - p.end) * 0.5 * (1 + Math.cos(Math.PI * q)); }
        const q = (x - p.warm) / (1 - p.warm);
