        const col = C[CAT[p.cat]];
        g.beginPath();
        for (let i = 0; i <= 300; i++) { const x = i / 300, yy = Y(lrAt(p, x)); if (!i) g.moveTo(X(x), yy); else g.lineTo(X(x), yy); }
        g.strokeStyle = col; g.lineWidth = 2.8; g.stroke();
