      const ctl = UI.controls(fig);
      const segL = nocase(UI.seg(ctl, { label: 'λ', options: LAMS.map((v) => ({ v, label: fmt(v, v >= 0.99 && v < 1 ? 3 : 2).replace(/0+$/, '').replace(/,$/, '') })), value: 0.95, onChange: (v) => { S.lam = v; upd(); } }));
