        V.text(g, 'Δθ₂', cx + 6, P.y + 14, { size: 11, font: 'mono', color: C.muted });
        V.text(g, 'KL = δ', X([0, rQ([0, 1])]) + 6, Y([0, rQ([0, 1])]) - 6, { size: 11, font: 'mono', color: C.a });
