        V.text(g, 'g', Q.x + 2 * cw + 18, y + 16, { size: 12, font: 'mono', weight: 600, color: C.muted });
        V.matrix(g, { x: Q.x + 2 * cw + 32, y, data: [[1], [1]], cell: cw * 0.8, cellH: 24, gap: 3, cmap: 'seq', min: 0, max: 3, values: true, fmt: (v) => fmt(v, 0) });
        y += 2 * 27 + 18;
