        rKL.set(fmt(s.KL, 3) + ' nat'); rX.set(fmt(s.ps[5] * 100, 1) + '%', s.ps[5] > 0.3 ? 'bad' : s.ps[5] > 0.08 ? 'warn' : 'ok');
