            if (S.mode === 'zieg') { const e = V.clamp((kl - S.tgt) / S.tgt, -0.2, 0.2); b = b * (1 + 0.1 * e); }
            else if (S.mode === 'ppo') { if (kl > 1.5 * S.tgt) b *= 2; else if (kl < S.tgt / 1.5) b /= 2; b = V.clamp(b, 1e-3, 10); }
