        const lmin = -3, lmax = 1;
        const F2 = frame(g, A2, 0, NIT, lmin, lmax, { xt: [0, 100, 200, 300], xf: (v) => String(v), yt: [-3, -2, -1, 0, 1], yf: (v) => (v === -3 ? '0,001' : v === -2 ? '0,01' : v === -1 ? '0,1' : v === 0 ? '1' : '10'), xl: 'iterações', yl: 'β (escala log)' });
