      const NAMES = ['política', 'crítico', 'referência', 'RM'];
      const targets = () => ({ ppo: [16 * S.N, 16 * S.N, 2 * S.N, 2 * S.N], grpo: [16 * S.N, 0, S.ref ? 2 * S.N : 0, S.rew === 'rm' ? 2 * S.N : 0] });
      let H = null;
