          const ax = barX(q.a) + bwid / 2, bx2 = barX(q.b) + bwid / 2;
          const ay = barBot - (S.cur[q.a] / S.scale) * barH, by2 = barBot - (S.cur[q.b] / S.scale) * barH;
          const mx = (ax + bx2) / 2, my = Math.min(ay, by2) - 30 - q.j * 30;
          const u = V.ease.inOut(q.t), uu = 1 - u;
