        g.strokeStyle = V.alpha(C.ink, 0.5); g.lineWidth = 1.4; g.stroke();
        const P = HH.pointer;
        if (P.down) { const q = bary(G, P.x, P.y); if (q.ok) { S.pi = q.p; S.ball = false; S.auto = false; S.trail = []; } }
