        const off = [[-6, 20], [6, 20], [0, -10]];
        for (let i = 0; i < 3; i++) {
          const al = i === 0 ? 'left' : i === 1 ? 'right' : 'center';
          const xx = corner[i][0] + (i === 0 ? -14 : i === 1 ? 14 : 0), yy = corner[i][1] + off[i][1];
          V.text(g, 'só ' + NM[i] + ' · r = ' + R[i], i === 2 ? xx : xx + (i === 0 ? 10 : -10), yy, { size: 11.5, weight: 600, color: C.ink, align: al });
        }
        // π_ref
        const qr = pt(G, REF);
