          if (c.ghost) { V.rr(g, lx + 0.5, yy - 9.5, 11, 11, 3); g.setLineDash([3, 2]); g.strokeStyle = V.alpha(C.ink, 0.7); g.lineWidth = 1.2; g.stroke(); g.setLineDash([]); }
          else V.box(g, lx, yy - 10, 12, 12, { r: 3, fill: V.alpha(c.c, 0.75) });
