      const W = [[1, 0.2], [1, -0.2], [0, 1]], NM = ['No', 'Never', 'Yes'];
      const S = { s: 0, play: true, hold: 0 };
      const probs = (s) => V.softmax([2 + 0.2 * s, 2 - 0.2 * s, s]);
      const CURV = Array.from({ length: 101 }, (_, k) => probs(k / 10));
      const ctl = UI.controls(fig);
