        V.text(g, 'unembeddings W e o estado oculto h', P1.x + 10, P1.y + 18, { size: 11.5, weight: 600, color: C.muted });
        const U = Math.min((P1.w - 80) / 1.45, (P1.h - 74) / 1.95);
