        V.text(g, 'margem No/Never = 0,4·s = ' + fmt(0.4 * s, 2) + ' → perda DPO ' + fmt(-logsig(0.4 * s), 3) + ' ↓', P2.x + 10, by, { size: 11.5, font: 'mono', color: C.a, maxW: P2.w - 20 });
        V.text(g, p[0] < 0.4683 && s > 1 ? 'mas p(No) caiu abaixo do início (0,468)!' : 'p(No) no início: 0,468', P2.x + 10, by + 19, { size: 11.5, color: p[0] < 0.4683 && s > 1 ? RED() : C.muted, weight: 600, maxW: P2.w - 20 });
        // --- P3: curvas ao longo de s
        const A = { x: P3.x + 40, y: P3.y + 28, w: P3.w - 56, h: P3.h - 58 };
        V.text(g, 'probabilidades ao longo do treino', P3.x + 10, P3.y + 18, { size: 11.5, weight: 600, color: C.muted });
        const ax = axes(g, A, [0, 10], [0, 1], { xlabel: 's', nx: 5, ny: 4 });
