        const narrow = w < 640;
        const A = narrow ? { x: 34, y: 34, w: w - 48, h: h * 0.42 } : { x: 34, y: 34, w: w * 0.56 - 40, h: h - 90 };
        const B = narrow ? { x: 40, y: A.y + A.h + 64, w: w - 56, h: h - (A.y + A.h + 64) - 40 } : { x: w * 0.56 + 34, y: 34, w: w * 0.44 - 50, h: h - 90 };
        // painel A: distribuições
