          if (fA > 0) { g.globalAlpha = appear * fA; const a = V.clamp(r.A / 0.4, -1, 1); cell(4, fmtS(r.A, 3), { fill: V.cmap(a, 'div'), color: Math.abs(a) > 0.55 ? C.bg : C.ink }); g.globalAlpha = appear; }
