            V.text(g, 'π(' + a + '|s)', lx - 6, yy + rowH / 2, { size: 10, font: 'mono', color: C.muted, align: 'right', base: 'middle' });
            g.fillStyle = V.alpha(C.muted, 0.1); V.rr(g, lx, yy + 2, lw, rowH - 5, 3); g.fill();
            const L = S.pol[s][j] * lw;
