          g.beginPath(); g.arc(vx - vr * 0.55, vy, vr, 0, Math.PI * 2); g.fillStyle = V.alpha(C.d, 0.2); g.fill(); g.strokeStyle = C.d; g.lineWidth = 1.4; g.stroke();
