            const ya = y1 + bs * 0.6 + 6, yb = y2 + bs * 0.6 + 6;
            const [cx, cy] = curveCtl(x1, ya, x2, yb, (i < j ? -1 : 1) * Math.min(60, Math.abs(x2 - x1) * 0.25 + 18));
