            V.box(g, hx + k * bw + 2, hy + hh - bh, bw - 4, Math.max(1, bh), { r: 3, fill: V.alpha(k === 0 ? C.a : C.f, k === a ? 0.8 : 0.3), stroke: k === 0 ? C.a : C.f, lw: k === a ? 1.6 : 0.8 });
