      const NX = 161, XS = Array.from({ length: NX }, (_, i) => -4 + (8 * i) / (NX - 1));
      const gauss = (x, m, s) => Math.exp(-0.5 * ((x - m) / s) ** 2) / (s * Math.sqrt(2 * Math.PI));
