      const tg = UI.toggle(ctl, { label: 'avançar sozinho', value: true, onChange: (v) => { S.auto = v; } });
      const rt = UI.readout(ctl, 't', '—'), rl = UI.readout(ctl, 'ℓ(t)', '—'), rw = UI.readout(ctl, 'peso σ(−t)', '—'), rtv = UI.readout(ctl, 'TV(p_data, p_θt)', '—');
