          g.fillStyle = r.col; V.rr(g, x, by, Math.max(4, L(r.v) * w), 9, 4); g.fill();
          if (r.ref != null) { const xr = x + L(r.ref) * w; V.line(g, xr, by - 4, xr, by + 13, { color: C.ink, lw: 1.4, dash: [2, 2] }); }
