          const L = Math.pow(2, S.bits) - 1;
          const aff = (row) => { const mn = Math.min(...row), mx = Math.max(...row), sc = (mx - mn) / L || 1e-12; const c = row.map((v) => Math.max(0, Math.min(L, Math.round((v - mn) / sc)))); return { c, d: c.map((k) => k * sc + mn), sc }; };
          q0 = []; q1 = []; d0 = []; d1 = [];
