          V.text(g, narrow ? 'calib.' : 'calibração', 16, by - 6, { size: 9.5, color: C.muted, base: 'middle' });
          V.text(g, 'MLP', 16, by + rowH * 1.5 + 3.5, { size: narrow ? 10 : 11, color: C.muted, base: 'middle' });
