        ['0%', '50%', '100%'].forEach((s, i) => V.text(g, s, XE(i / 2), py0 + ph2 + 13, { size: 10, font: 'mono', color: C.muted, align: i === 0 ? 'left' : i === 2 ? 'right' : 'center' }));
