      UI.seg(ctl, { label: 'Referência da quantização', options: [{ v: 'merge', label: 'merge BF16 (certo)' }, { v: 'base', label: 'base original (errado)' }], value: 'merge', onChange: (v) => { S.ref = v; upd(); } });
