      const kSlots = () => { const order = []; KT.forEach((a) => { if (a >= 0 && !order.includes(a)) order.push(a); }); return order.slice(0, S.maxL); };
      const SUB = ['₁', '₂', '₃', '₄', '₅', '₆'];
